    { word: "view", phonetic: "/vjuː/", partOfSpeech: "noun", meaningZh: "观点", exampleEn: "In my view, the plan needs more public discussion.", exampleZh: "在我看来，这个计划需要更多公众讨论。" },
    { word: "whereas", phonetic: "/ˌweərˈæz/", partOfSpeech: "conjunction", meaningZh: "而", exampleEn: "The north receives more rain, whereas the south is usually dry.", exampleZh: "北部降雨更多，而南部通常干燥。" },
    { word: "widespread", phonetic: "/ˈwaɪdspred/", partOfSpeech: "adjective", meaningZh: "广泛的", exampleEn: "There was widespread support for the new park.", exampleZh: "新公园得到了广泛支持。" },
    { word: "aspect", phonetic: "/ˈæspekt/", partOfSpeech: "noun", meaningZh: "方面", exampleEn: "Cost is only one aspect of the decision.", exampleZh: "费用只是这个决定的一个方面。" }
